#!/usr/bin/env python3
"""
Round 114b (tiles), 29 September 2026.

New builds: sports_facilities (Overture Maps), sports_betting and
sports_fixing (Wikidata), pet_food_world (Wikidata), animal_places_osm
(OpenStreetMap breeding places, zoos and aquariums, and a count of aquariums
in the Zoos map); shared helpers lib/wdtools.py and lib/pointtiles.py; the
holidays file cut to those who corporatized holidays.

Whole files, each written only if it differs.
"""
import base64, pathlib

FILES = {'scripts/lib/wdtools.py': '', 'scripts/lib/pointtiles.py': '', 'scripts/sports_facilities.py': '', 'scripts/sports_betting.py': '', 'scripts/sports_fixing.py': '', 'scripts/pet_food_world.py': '', 'scripts/animal_places_osm.py': '', 'holidays/culprits.geojson': ''}
DELETE = []


def main():
    for p, b in FILES.items():
        data = base64.b64decode(b)
        f = pathlib.Path(p)
        if f.exists() and f.read_bytes() == data:
            print(f"round114b: {p} already up to date")
            continue
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_bytes(data)
        print(f"round114b: wrote {p}")
    for p in DELETE:
        f = pathlib.Path(p)
        if f.exists():
            f.unlink()
            print(f"round114b: deleted {p}")


if __name__ == "__main__":
    main()
